void combat(Ninja a, Ninja b) {
    printf("Le combat commence entre %s et %s!\n", a.nom, b.nom);
    while (a.vie > 0 && b.vie > 0) {
        // Ninja a attaque Ninja b
        float jet_a = (float)rand() / RAND_MAX;
        if (jet_a > b.esquive) {
            float degats_a = a.attaque - b.defense;
            if (degats_a < 0){
