        return augment(e + 1, taille - 1);
    }
}

Employe *rechercher(Employe *e, int taille, int num)
{
    // verification paramètre (pas obligatoire au DS2 mais obligatoire au DS3)
    if (e == NULL || taille < 0)
    {
        exit(7);
    }

    int a = 0;
    int b = taille - 1;
    int m = (a + b) / 2;
    while (a <= b)
    {
        if (e[m].num == num)
        {
            return e + m;
        }
        else if (e[m].num < num)
        {
            a = m + 1;
        }
        else
        {
            b = m - 1;
        }
        m = (a + b) / 2;
    }
    return NULL;
}
