Chainon* insertDebut(Chainon* pliste, char* a) {
    // Vérification que la chaîne n'est pas nulle et ne dépasse pas la taille maximale
    if (a == NULL || strlen(a) > MAX_C) {
        exit(EXIT_FAILURE);  // Si oui, on quitte le programme
