        actual->diametre = temp->diametre;
        actual->next = NULL;
        file = inserFile(file, actual);
        temp = temp->next;
        tete = suppPile(tete);

        i++;
    }
    // Remettre les éléments de la file dans la pile pour les inverser
    while (file != NULL) {
