def Base(j, X, x):
    l = 1
    for k in range(0, len(X)):
        if k != j:
            l = l * (x - X[k])/(X[j] - X[k])
    return l

def Lagrange1(f, X, x):
    P = 0
    for k in range(0, len(X)):
        P = P + f(X[k]) * Base(k, X, x)
