if (numtasks % 4 != 0) {
   printf("Quitter. Nombre de processus doit �tre divisible par 4.\n");
   MPI_Abort(MPI_COMM_WORLD, rc);
   exit(0);
   }

chunksize = (ARRAYSIZE / numtasks);
tag2 = 1;
tag1 = 2;

MPI_Comm_rank(MPI_COMM_WORLD,&taskid);
printf ("traitement de la tache  %d a demarre...\n", taskid);

/***** tache maitre uniquement ******/
if (taskid == MASTER){

  /* Initialise le tableau */
  sum = 0;
  for(i=0; i<ARRAYSIZE; i++) {
    data[i] =  i * 1.0;
    }
 // printf("tableau initialise, la somme = %e\n",sum);

  /* Envoie a chaque processus sa tranche de tableau - 
  le processus maitre garde la 1er tranche. 
  Offset du prochaine tache commence � partif de l'index egal
  a l'offset*/
  offset = chunksize;
  for (dest=1; dest<numtasks; dest++) {

MPI_Send(&offset, 1, MPI_INT, dest, tag1, MPI_COMM_WORLD);
