double get_time() {  
       struct timeval tv;  
       gettimeofday(&tv, (void *)0);  
       return (double) tv.tv_sec + tv.tv_usec*1e-6;
}*/

double calcul_pi_parallel(int nb_threads, long N){  
       double start,stop;  
       double cpu_time_used; 
       int i = 0;  
       double value_pi = 0.0;  
       double sumFX = 0.0;  
       double X;  
       double h = 1.0 / (double)N;  
       start = omp_get_wtime();  
       #pragma omp parallel for num_threads(nb_threads) \
	      private(X) reduction(+:sumFX)  
       for(i = 1; i < N; i++) {    
             X = h * (i - 0.5);    
             sumFX +=  4.0/(1.0 + X*X);  
             }  
       value_pi= h * sumFX;

stop = omp_get_wtime();
	   cpu_time_used = stop-start;  
       printf("value of pi %1.12f\n",value_pi);     
       return cpu_time_used;
}

